import { mount } from 'lithent';
import { CodeBlock } from '@/components/CodeBlock';
import { navigateTo } from '@/store';

export const CtxCommands = mount(() => {
  return () => (
    <div class="page-sheet">
      <h1>ctx Commands</h1>

      <p>
        The <code>ctx</code> resource stores branch-scoped project context.
        Keys can be automatically inferred from git repository name and branch.
      </p>

      <h2>Key Inference</h2>
      <p>
        When no key is provided, ctxbin automatically infers the key.
        See <span onClick={() => navigateTo('/guide/key-inference')} class="text-indigo-600 hover:underline cursor-pointer">Key Inference</span> for details.
      </p>
      <CodeBlock
        language="text"
        code={`key = {project}/{branch}
project = package.json "name" field, or folder name if no package.json
branch  = git rev-parse --abbrev-ref HEAD`}
      />
      <p>This requires running inside a git repository.</p>
      <p class="mt-4 p-3 bg-gray-100 dark:bg-gray-800 rounded text-sm">
        <strong>Note:</strong> If <code>package.json</code> exists, the <code>name</code> field is used as the project name.
        If the name differs from the folder name, a warning is printed to stderr.
        Without <code>package.json</code>, the folder name is used (not the git remote URL—parsing remote URLs across different git services is fragile).
      </p>

      <h2>Load</h2>
      <p>Load context from Redis:</p>
      <CodeBlock
        language="bash"
        code={`# Auto-key (inferred from git)
$ npx ctxbin ctx load

# Explicit key
$ npx ctxbin ctx load my-project/main`}
      />
      <p>
        Use <code>--raw</code> to print the stored value exactly as-is (including metadata wrapper):
      </p>
      <p>
        <code>--raw</code> is intended for sync/migration exact-payload workflows and prints a warning by default.
        Set <code>CTXBIN_SUPPRESS_RAW_WARN=1</code> in automation to suppress it.
      </p>
      <CodeBlock
        language="bash"
        code={`$ npx ctxbin ctx load my-project/main --raw`}
      />

      <h2>Save (Replace)</h2>
      <p>Save new context, replacing any existing value:</p>
      <p>
        Explicit keys are useful outside git repos, but are not recommended for normal use.
      </p>
      <CodeBlock
        language="bash"
        code={`# From --value flag
$ npx ctxbin ctx save --value "markdown string"

# From file
$ npx ctxbin ctx save --file context.md

# From stdin
$ cat context.md | npx ctxbin ctx save

# With explicit key
$ npx ctxbin ctx save my-project/main --file context.md`}
      />
      <p>
        Use <code>--raw</code> to store the input value exactly as-is (no metadata injection/update):
      </p>
      <CodeBlock
        language="bash"
        code={`$ npx ctxbin ctx save my-project/main --raw --file context.md`}
      />

      <h2>Save (Append)</h2>
      <p>Append to existing context (separator: <code>\n\n</code>):</p>
      <CodeBlock
        language="bash"
        code={`$ npx ctxbin ctx save --append --file note.md
$ npx ctxbin ctx save my-project/main --append --value "additional notes"`}
      />
      <p>If the key does not exist, behaves the same as normal save.</p>
      <p><code>--append</code> cannot be combined with <code>--raw</code>.</p>

      <h2>List</h2>
      <p>List all stored contexts:</p>
      <CodeBlock
        language="bash"
        code={`$ npx ctxbin ctx list
my-project/main    --value
my-project/feature --value`}
      />

      <h2>Delete</h2>
      <p>Delete a context:</p>
      <CodeBlock
        language="bash"
        code={`# Auto-key
$ npx ctxbin ctx delete

# Explicit key
$ npx ctxbin ctx delete my-project/main`}
      />
      <ul>
        <li>No confirmation prompt (agent-safe)</li>
        <li>Fails fast if key cannot be inferred</li>
      </ul>

      <h2>Context and Installation Sync</h2>
      <p><code>ctxbin sync</code> installs remote skills and agents into local Claude Code/Codex. It does not access context or use branch key inference, and it does not require --raw. For local/remote context replication, use the companion ctxloc. See <span onClick={() => navigateTo('/commands/sync')} class="text-indigo-600 hover:underline cursor-pointer">skill/agent sync commands</span> for local installation.</p>

      <h2>Redis Mapping</h2>
      <CodeBlock
        language="text"
        code={`Redis Key (HASH): ctx
Field           : {project}/{branch}
Value           : markdown string (UTF-8)`}
      />
    </div>
  );
});
