import { mount } from 'lithent';
import { CodeBlock } from '@/components/CodeBlock';
import { navigateTo } from '@/store';

export const ErrorCodesKo = mount(() => {
  return () => (
    <div class="page-sheet">
      <h1>에러 코드</h1>

      <p>
        모든 ctxbin 에러는 <code>stderr</code>에 기록되며 종료 코드 <code>1</code>로 종료됩니다.
        에러는 쉬운 파싱을 위해 단일 줄 형식을 사용합니다.
      </p>

      <h2>에러 형식</h2>
      <CodeBlock
        language="text"
        code={`CTXBIN_ERR <CODE>: <message>`}
      />

      <h2>에러 코드</h2>

      <table>
        <thead>
          <tr>
            <th>코드</th>
            <th>설명</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td><code>INVALID_INPUT</code></td>
            <td>누락, 추가 또는 결합된 플래그; 잘못된 인자</td>
          </tr>
          <tr>
            <td><code>MISSING_KEY</code></td>
            <td>키가 필요하지만 제공되지 않음 (agent/skill 명령어)</td>
          </tr>
          <tr>
            <td><code>INVALID_URL</code></td>
            <td>skillref에 대해 URL 형식이 잘못됨</td>
          </tr>
          <tr>
            <td><code>INVALID_REF</code></td>
            <td>커밋 SHA가 40자 16진수 형식이 아님</td>
          </tr>
          <tr>
            <td><code>INVALID_PATH</code></td>
            <td>경로에 탐색이 포함되거나 잘못됨</td>
          </tr>
          <tr>
            <td><code>NOT_IN_GIT</code></td>
            <td>키 추론에 git 저장소가 필요하지만 안에 있지 않음</td>
          </tr>
          <tr>
            <td><code>NOT_FOUND</code></td>
            <td>키 또는 원격 경로가 존재하지 않음</td>
          </tr>
          <tr>
            <td><code>TYPE_MISMATCH</code></td>
            <td>값 타입에 잘못된 플래그 (예: 문자열에 --dir)</td>
          </tr>
          <tr>
            <td><code>SIZE_LIMIT</code></td>
            <td>tarball 또는 다운로드가 크기 제한 초과</td>
          </tr>
          <tr>
            <td><code>NETWORK</code></td>
            <td>저장소 또는 가져오기 요청 실패</td>
          </tr>
          <tr>
            <td><code>IO</code></td>
            <td>파일 시스템 또는 파싱 에러</td>
          </tr>
        </tbody>
      </table>

      <h2>예제</h2>
      <CodeBlock
        language="text"
        code={`CTXBIN_ERR NOT_IN_GIT: must run inside a git repository
CTXBIN_ERR MISSING_KEY: key is required
CTXBIN_ERR NOT_FOUND: no value for ctx:my-project/main
CTXBIN_ERR SIZE_LIMIT: skillpack tar.gz exceeds 7MB limit
CTXBIN_ERR TYPE_MISMATCH: --dir cannot be used with string values`}
      />

      <h2>Sync 오류와 복구</h2>
      <CodeBlock language="text" code={`CTXBIN_ERR INVALID_INPUT: sync requires --target claude, codex, or all
CTXBIN_ERR INVALID_INPUT: directory overrides require a single --target
CTXBIN_ERR INVALID_INPUT: skill my-skill: bundle must contain root SKILL.md
CTXBIN_ERR INVALID_PATH: sync destination directories must not overlap`} />
      <p>잘못된 메타데이터·설치 이력과 지원하지 않는 에이전트 필드는 INVALID_INPUT을 반환합니다. 위험한 이름·심볼릭 링크·예상과 다른 대상 유형은 INVALID_PATH입니다. 원격 저장소·GitHub 실패는 --dry-run에서도 NETWORK를 반환합니다.</p>
      <p>IO는 권한, 사용 중인 .ctxbin-sync.lock, 변경된 설치 이력, 적용·복구 실패를 나타낼 수 있습니다. 일반 적용 실패는 파일과 이력을 복원합니다. 복구가 완료되지 않으면 오류에 보존된 백업 경로를 표시하므로 journal.json과 백업을 확인한 뒤 재시도하세요. 프로세스 중단은 복구 보장 범위 밖입니다. 자세한 내용은 <span onClick={() => navigateTo('/commands/sync')} class="text-indigo-600 hover:underline cursor-pointer">sync 복구 안내</span>를 참고하세요.</p>

      <h2>에러 파싱</h2>
      <CodeBlock
        language="bash"
        code={`# 에러 코드 추출
$ npx ctxbin ctx load 2>&1 | grep -oP 'CTXBIN_ERR \\K[A-Z_]+'

# 특정 에러 확인
$ npx ctxbin ctx load 2>&1 | grep -q "CTXBIN_ERR NOT_FOUND" && echo "not found"`}
      />
      <p>없는 선택 이름은 선택 대상의 같은 저장소 설치 이력이 prune 후보로 확인되지 않으면 NOT_FOUND입니다. 잘못된 백업·체크섬, force 없는 파일 교체, 빈 결과·다른 저장소 백업 교체 거부는 INVALID_INPUT입니다. 파일 오류는 IO이며 미완료 복구 롤백은 최초 오류 코드(NETWORK 포함)를 유지하고 CTXBIN_ERR 접두어를 한 번만 출력합니다. 미리보기에도 원격 접근이 필요합니다. 자세한 내용은 <span onClick={() => navigateTo('/commands/backup-restore')} class="text-indigo-600 hover:underline cursor-pointer">백업·복구 안내</span>.</p>
    </div>
  );
});
